import { Component } from '@angular/core';
import { SaleService } from 'src/app/services/sale.service';
import { Sale } from 'src/app/models/sale.model';

@Component({
  selector: 'app-sale-form',
  templateUrl: './sale-form.component.html',
  styleUrls: ['./sale-form.component.css'],
})
export class SaleFormComponent {
  sale: Sale = {
    productName: '',
    customerName: '',
    quantity: 0,
    price: 0,
    deliveryStatus: 'Pending',
  };

  constructor(private saleService: SaleService) {}

  onSubmit() {
    this.saleService.createSale(this.sale).subscribe(() => {
      alert('Sale added successfully');
      this.sale = {
        productName: '',
        customerName: '',
        quantity: 0,
        price: 0,
        deliveryStatus: 'Pending',
      };
    });
  }
}
<h2>Add New Sale</h2>

<form (ngSubmit)="onSubmit()" #saleForm="ngForm">
  <input
    type="text"
    [(ngModel)]="sale.productName"
    name="productName"
    placeholder="Product Name"
    required
  />
  <input
    type="text"
    [(ngModel)]="sale.customerName"
    name="customerName"
    placeholder="Customer Name"
    required
  />
  <input
    type="number"
    [(ngModel)]="sale.quantity"
    name="quantity"
    placeholder="Quantity"
    required
  />
  <input
    type="number"
    [(ngModel)]="sale.price"
    name="price"
    placeholder="Price"
    required
  />

  <select [(ngModel)]="sale.deliveryStatus" name="deliveryStatus">
    <option value="Pending">Pending</option>
    <option value="Delivered">Delivered</option>
  </select>

  <button type="submit">Add Sale</button>
</form>
